'use strict';
const attendanceDrafts=new Map();let attendanceShownKey=null;
function selectedEmptyCity(){const ref=selectedMapItem;if(ref?.kind!=='slot')return null;const s=slotBy(ref.id);return s&&!memberAt(s.id)?s:null}
function queueTrap(){return selectedEmptyCity()?.trap||+state.operations.rosterGroup}
function assignQueuedPlayer(id){try{const m=state.members.find(m=>m.id===id);if(!m||!m.trap){memberDetail(id);return}const target=Hive.nextAvailableCity(state,m.trap,selectedEmptyCity()?.id);if(!target){toast('Add a city space or choose a layout first.');return}const next=Hive.assignAvailableSlotMember(state,target.id,id);$('#queueSearch').value='';commit(()=>state=next);selectedMapItem={kind:'member',id};selectedSlot=target.id;renderMap();renderQueue();toast(m.name+' placed. Undo is available.')}catch(e){toast(e.message)}}
renderQueue=function(){const trap=queueTrap();$('#addToBTList').textContent=trap?'Add players to BT '+trap:'Add players to a BT list';$('#addToBTList').disabled=readonly;$('#syncBTLists').disabled=readonly;$$('#queueTrapTabs button').forEach(b=>b.classList.toggle('active',+b.dataset.queueTrap===trap));const q=$('#queueSearch').value||'',group=trap?Hive.slotAttendanceGroup(state,trap,{query:q}):null,list=trap?group.members:state.members.filter(m=>!m.trap&&!m.slot&&(m.name+' '+m.playerId).toLocaleLowerCase().includes(q.toLocaleLowerCase()));$('#queueHeading').textContent=selectedEmptyCity()?'Who goes here?':'Players to place';$('#queueGroupLabel').textContent=group?.kind?'BT '+trap+' · '+group.label+' · '+group.groupCount:trap?'':'Choose a BT group to place these players.';const html=list.map(m=>`<button class="queue-row" ${readonly?'disabled':''} data-queue-player="${esc(m.id)}"><span>${esc(m.name)}</span><small>${trap?'Place →':'Edit player →'}</small></button>`).join('')||`<p class="muted">${group?.remaining?'No matches in this attendance group.':state.members.some(m=>m.trap===trap)?'All players for this trap are assigned.':'Add players in Players to get started.'}</p>`;if($('#queue').dataset.renderKey!==html){$('#queue').dataset.renderKey=html;$('#queue').innerHTML=html;$$('[data-queue-player]').forEach(b=>b.onclick=()=>assignQueuedPlayer(b.dataset.queuePlayer))}$('#suggestBtn').disabled=readonly||!trap||!Hive.slotAttendanceGroup(state,trap).remaining||!Hive.nextAvailableCity(state,trap);$('#suggestBtn').hidden=!!selectedEmptyCity()||!trap||!Hive.slotAttendanceGroup(state,trap).remaining;};
$('#queueSearch').oninput=renderQueue;
$('#suggestBtn').onclick=()=>{try{const result=Hive.placeUnassignedPlayers(state,queueTrap());if(!result.placed.length){toast('No empty, valid city spaces are available.');return}commit(()=>state=result.state);selectedMapItem=null;selectedSlot=null;renderMap();renderQueue();toast(result.placed.length+' players placed. Undo is available.')}catch(e){toast(e.message)}};
// Keep the active item tool visible without adding permanent toolbar buttons.
const simpleTool=setTool;setTool=function(t){simpleTool(t);$('#itemMenu').open=false;$('#itemMenu').classList.toggle('active',['flag','block','hq'].includes(t));$('#itemMenu').setAttribute('aria-label',['flag','block','hq'].includes(t)?'Add item · '+({flag:'Banner',block:'Terrain',hq:'HQ'})[t]+' selected':'Add item')};
$$('[data-tool]').forEach(b=>b.onclick=()=>{togglePlacementTool(b.dataset.tool);renderQueue()});
const simpleQueueTabs=renderQueueTabs;renderQueueTabs=function(){simpleQueueTabs();$$('[data-queue-trap]').forEach(b=>{const choose=b.onclick;b.onclick=()=>{selectedMapItem=null;selectedSlot=null;choose()}})};
function attendanceDraft(){const o=state.operations,key=Hive.attendanceSessionKey(o.date,o.trap),r=Hive.attendanceSession(state),token=JSON.stringify(r||null),old=attendanceDrafts.get(key);if(old&&old.token===token){if(!r)state.members.filter(m=>m.trap===o.trap).forEach(m=>old.eligible.add(m.id));return old;}const draft={key,token,checked:new Set(r?.attended||[]),eligible:new Set(r?.eligible||state.members.filter(m=>m.trap===o.trap).map(m=>m.id)),complete:!!r?.complete,query:''};attendanceDrafts.set(key,draft);return draft}
function attendancePeople(draft){return state.members.filter(m=>m.trap===state.operations.trap||draft.checked.has(m.id)||draft.eligible.has(m.id)).sort((a,b)=>a.name.localeCompare(b.name))}
function updateAttendanceSave(){const d=attendanceDraft();$('#saveSimpleAttendance').textContent='Save '+attendeeLabel(d.checked.size)+' to BT'+state.operations.trap+' · '+attendanceDateLabel(state.operations.date);$('#attendanceDraftCount').textContent=d.checked.size+' selected';}
function renderAttendanceNames(){
 const d=attendanceDraft(),q=d.query.trim(),results=$('#attendanceNameSuggestions');
 results.innerHTML=q?Hive.rosterSuggestions(state,q).map(c=>`<button type="button" class="queue-row" data-attendance-match="${esc(c.id)}" ${readonly?'disabled':''}><span>${esc(c.member.name)}<small>${esc(c.member.playerId||'No player ID')} · ${c.member.trap?'BT '+c.member.trap:'Other players'}</small></span><small>${d.checked.has(c.id)?'Selected':'Add'}</small></button>`).join('')||'<p class="muted">No roster match. Add the player in Players first.</p>':'';
 $$('[data-attendance-match]').forEach(b=>b.onclick=()=>{d.checked.add(b.dataset.attendanceMatch);d.eligible.add(b.dataset.attendanceMatch);d.query='';$('#attendanceNameSearch').value='';renderAttendanceNames();updateAttendanceSave()});
 const people=q?[]:attendancePeople(d);
 $('#attendanceNames').innerHTML=people.map(m=>`<label class="attendance-name"><input type="checkbox" data-simple-attendee="${esc(m.id)}" ${d.checked.has(m.id)?'checked':''} ${readonly?'disabled':''}><span>${esc(m.name)}</span>${m.trap!==state.operations.trap?'<small>Other group</small>':''}</label>`).join('')||(q?'':'<p class="muted">Type a name above to add an attendee.</p>');
 $$('[data-simple-attendee]').forEach(el=>el.onchange=()=>{if(el.checked){d.checked.add(el.dataset.simpleAttendee);d.eligible.add(el.dataset.simpleAttendee)}else d.checked.delete(el.dataset.simpleAttendee);updateAttendanceSave()})
}
renderAttendance=function(){const o=state.operations,r=Hive.attendanceSession(state),d=attendanceDraft();if(attendanceShownKey!==d.key){$('#attendanceSavedReceipt').classList.add('hidden');attendanceShownKey=d.key;}$('#attendanceSummary').innerHTML=`<div class="attendance-heading"><h2>Who attended BT ${o.trap}?</h2><p>${attendanceDateLabel(o.date,true)} · ${esc(state.settings['time'+o.trap])} UTC</p><div class="event-summary-status"><span class="event-state ${r?.complete?'complete':r?'partial':'unrecorded'}">${r?.complete?'Complete':r?'Partial':'Not recorded'}</span><small>${r?.attended.length||0} saved · Every 2 days</small></div></div>`;$('#attendanceSession').innerHTML=`<section class="card simple-attendance"><label>Find a player<input id="attendanceNameSearch" type="search" placeholder="Type any roster name or player ID" autocomplete="off" aria-controls="attendanceNameSuggestions" value="${esc(d.query)}"></label><div id="attendanceNameSuggestions" aria-label="Matching roster players" aria-live="polite"></div><div id="attendanceNames"></div><div class="attendance-list-state"><label class="check"><input id="simpleComplete" type="checkbox" ${d.complete?'checked':''} ${readonly?'disabled':''}> This is the full list</label><small>Unlisted eligible players count as absent only for a full list.</small></div><div class="attendance-save"><small id="attendanceDraftCount"></small><button class="primary" id="saveSimpleAttendance" ${readonly?'disabled':''}>Save attendees</button></div></section>`;$('#attendanceNameSearch').oninput=e=>{d.query=e.target.value;renderAttendanceNames()};$('#simpleComplete').onchange=e=>d.complete=e.target.checked;$('#saveSimpleAttendance').onclick=()=>{try{const next=Hive.saveAttendanceSession(state,{date:o.date,trap:o.trap,selected:[...d.checked],eligible:[...d.eligible],complete:d.complete,replace:true});commit(()=>state=next);attendanceReceipt();toast('Saved '+attendeeLabel(d.checked.size)+' to '+attendanceDestination()+'.')}catch(e){toast(e.message)}};renderAttendanceNames();updateAttendanceSave();const logs=Object.values(state.attendanceLog.sessions).filter(x=>x.trap===o.trap).sort((a,b)=>b.date.localeCompare(a.date));$('#attendanceHistory').innerHTML=logs.map(x=>`<button class="history-row" data-session-date="${esc(x.date)}"><strong>${esc(x.date)}</strong><span>${x.attended.length} attended</span><span class="pill">${x.complete?'Complete':'Partial'}</span></button>`).join('')||'<p class="muted">No saved events yet.</p>';$$('[data-session-date]').forEach(b=>b.onclick=()=>{commit(()=>state.operations.date=b.dataset.sessionDate);$('#attendanceSession').scrollIntoView?.({behavior:'smooth',block:'start'})})};
// Default phone framing favours legible cities. Fit still shows the full layout.
function focusPlanningMap(){if(page!=='map'||activeTrap==='all')return;const t=state.traps.find(t=>String(t.id)===activeTrap);if(!t)return;const p=projected(t.x+t.w/2,t.y+t.h/2);camera.k=Math.max(camera.k,36);camera.x=view.w/2-p.x*camera.k;camera.y=view.h/2-p.y*camera.k;renderMap()}
$$('#trapTabs button,[data-map-mode]').forEach(b=>{const prior=b.onclick;b.onclick=()=>{prior();focusPlanningMap()}});
const simpleNavigate=navigate;navigate=function(p){simpleNavigate(p);if(p==='map')setTimeout(focusPlanningMap,10)};
function openBTListEditor(){
 const chosen=new Set();const initial=queueTrap()||1;
 openModal(`<h2>Add players to a BT list</h2><label>BT list<select id="listDestination"><option value="1" ${initial===1?'selected':''}>BT 1</option><option value="2" ${initial===2?'selected':''}>BT 2</option><option value="0">Other players</option></select></label><label>Find a roster player<input id="btListSearch" type="search" placeholder="Name or player ID" autocomplete="off" aria-controls="btListMatches"></label><div id="btListMatches" aria-live="polite"></div><div id="btListChosen"></div><label>Manual frequency<select id="btListFrequency"><option value="keep">Keep current frequency</option><option value="regular">Frequently</option><option value="sometimes">Sometimes</option><option value="rarely">Rarely</option><option value="unknown">Unknown</option></select></label><small>Completed event records take priority over manual frequency.</small><label class="check"><input id="btListAuto" type="checkbox" checked> Update this BT list from attendance</label><small>Uses recorded visits from the latest ${state.attendanceLog.settings.window} finished events per trap. Ties keep the current list. Placed or locked cities stay put.</small><button id="saveBTList" class="primary full" disabled>Add players</button>`);
 const draw=()=>{
  const q=$('#btListSearch').value,group=+$('#listDestination').value;
  $('#btListMatches').innerHTML=q.trim()?Hive.rosterSuggestions(state,q).filter(c=>!chosen.has(c.id)).map(c=>`<button class="queue-row" data-list-match="${esc(c.id)}"><span>${esc(c.member.name)}<small>${esc(c.member.playerId||'No player ID')} · ${c.member.trap?'BT '+c.member.trap:'Other players'} · ${group?esc(Hive.attendanceStats(state,c.member,group).label):'Other players'}</small></span><small>Add</small></button>`).join('')||'<p class="muted">No more matches.</p>':'';
  $('#btListChosen').innerHTML=[...chosen].map(id=>`<button class="queue-row" data-unpick-list="${esc(id)}">${esc(state.members.find(m=>m.id===id).name)} <small>Remove ×</small></button>`).join('');
  $$('[data-list-match]').forEach(b=>b.onclick=()=>{chosen.add(b.dataset.listMatch);$('#btListSearch').value='';draw();$('#btListSearch').focus()});
  $$('[data-unpick-list]').forEach(b=>b.onclick=()=>{chosen.delete(b.dataset.unpickList);draw()});
  $('#saveBTList').textContent='Add '+chosen.size+' players to '+(group?'BT '+group:'Other players');$('#saveBTList').disabled=!chosen.size;
 };
 $('#btListSearch').oninput=draw;$('#listDestination').onchange=draw;
 $('#saveBTList').onclick=()=>{try{const group=+$('#listDestination').value,next=Hive.setRosterGroup(state,[...chosen],group,{automatic:$('#btListAuto').checked,kind:$('#btListFrequency').value});commit(()=>state=next);closeModal();toast(chosen.size+' players added to '+(group?'BT '+group:'Other players')+'. Undo is available.')}catch(e){toast(e.message)}};draw();
}
$('#addToBTList').onclick=openBTListEditor;
$('#syncBTLists').onclick=()=>{commit(()=>state=Hive.routeAttendanceGroups(state));const pending=state.members.filter(m=>m.suggestedAttendanceTrap!==undefined);toast(pending.length?'BT lists updated. '+pending.length+' placed or locked players need review.':'BT lists updated from attendance. Undo is available.')};
const groupedRenderQueue=renderQueue;renderQueue=function(){document.querySelector('.attendance-group-review')?.remove();groupedRenderQueue();const trap=queueTrap(),pending=state.members.filter(m=>m.suggestedAttendanceTrap!==undefined&&(m.trap===trap||m.suggestedAttendanceTrap===trap));if(pending.length){const box=document.createElement('div');box.className='attendance-group-review';box.innerHTML='<p class="muted">Suggested list changes · cities stay fixed</p>'+pending.map(m=>`<button class="queue-row" data-review-group="${esc(m.id)}">${esc(m.name)}<small>Suggested ${m.suggestedAttendanceTrap?'BT '+m.suggestedAttendanceTrap:'Other players'} · Review</small></button>`).join('');$('#queue').append(box);$$('[data-review-group]').forEach(b=>b.onclick=()=>memberForm(state.members.find(m=>m.id===b.dataset.reviewGroup)))}};
const attendanceGroupsOnLoad=Hive.routeAttendanceGroups(state);if(!readonly&&JSON.stringify(attendanceGroupsOnLoad)!==JSON.stringify(state))commit(()=>state=attendanceGroupsOnLoad);
render();setTimeout(focusPlanningMap,35);
